import React, { useEffect, useState } from 'react';
import { loadSvg } from '../utils/contentLoader';

interface SketchFigureProps {
  /** Content-root path, e.g. /content/part-04-.../diagrams/25.1-soft-lookup.svg */
  src: string;
  alt: string;
  caption?: string;
}

/**
 * Renders a lesson diagram. SVGs are inlined (not <img>) so their --sk-* colour
 * tokens follow the site's light/dark theme. They come from this repo's own
 * content folder (generated by scripts/diagrams), so inlining is safe.
 */
export const SketchFigure: React.FC<SketchFigureProps> = ({ src, alt, caption }) => {
  const [svg, setSvg] = useState<string | null>(null);
  const [missing, setMissing] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setSvg(null);
    setMissing(false);
    loadSvg(src).then((text) => {
      if (cancelled) return;
      if (text) setSvg(text);
      else setMissing(true);
    });
    return () => {
      cancelled = true;
    };
  }, [src]);

  return (
    <figure className="sketch-figure my-8">
      <div
        role="img"
        aria-label={alt}
        className="rounded-2xl border border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900/60 p-4 sm:p-6 overflow-x-auto min-h-[120px]"
      >
        {svg && <div className="min-w-[560px]" dangerouslySetInnerHTML={{ __html: svg }} />}
        {missing && <p className="text-sm text-rose-500">Diagram not found: {src}</p>}
      </div>
      {caption && (
        <figcaption className="mt-3 text-center text-sm text-slate-500 dark:text-slate-400">{caption}</figcaption>
      )}
    </figure>
  );
};
